from math import gcd
from typing import List


def kth_smallest_amount(coins: List[int], k: int) -> int:
    """Return the k-th distinct positive multiple of any given denomination.

    Coins cannot be combined across denominations. There are 1-15 distinct
    positive denominations, each at most 25, and 1 <= k <= 2 * 10**9.

    >>> kth_smallest_amount([3, 6, 9], 3)
    9
    >>> kth_smallest_amount([5, 2], 7)
    12
    """
    # Multiples of a retained smaller divisor add no new amounts.
    divisors = []
    for coin in sorted(set(coins)):
        if not any(coin % divisor == 0 for divisor in divisors):
            divisors.append(coin)

    upper = divisors[0] * k
    # Aggregate inclusion-exclusion terms with the same least common multiple.
    # A term exceeding the search bound contributes zero throughout the search.
    terms = {}
    for coin in divisors:
        changes = {coin: 1}
        for multiple, coefficient in terms.items():
            common = multiple // gcd(multiple, coin) * coin
            if common <= upper:
                changes[common] = changes.get(common, 0) - coefficient
        for multiple, coefficient in changes.items():
            terms[multiple] = terms.get(multiple, 0) + coefficient
            if terms[multiple] == 0:
                del terms[multiple]

    lower = 1
    while lower < upper:
        middle = (lower + upper) // 2
        count = sum(coefficient * (middle // multiple)
                    for multiple, coefficient in terms.items())
        if count >= k:
            upper = middle
        else:
            lower = middle + 1
    return lower

def count_good_string_replacements(n: int, k: int, s: str) -> int:
    """Count replacements with at least k deletable nonempty substrings.

    Identical pairs and triples containing A, B, C may be deleted.
    The answer is returned modulo 998244353; n is the length of s.
    """
    mod = 998244353
    if k == 0:
        return pow(3, s.count("?"), mod)
    # Adjacent prefix states differ, so a state can occur at most
    # ceil((n+1)/2) times. Alternating two states maximizes equal pairs.
    if k > (n * n) // 4:
        return 0

    # Map A, B, C to the nonzero elements of the Klein four group.
    # A substring is deletable iff its group sum is zero: its three
    # character counts have the same parity. Thus its endpoints have
    # identical prefix states.
    #
    # Store visit counts relative to the current prefix state, which is
    # always index zero. Translating the four labels preserves all edges.
    dp = {(1, 0, 0, 0): 1}
    for ch in s:
        nxt = {}
        allow_a = ch in "A?"
        allow_b = ch in "B?"
        allow_c = ch in "C?"
        for (a, b, c, d), ways in dp.items():
            if allow_a:
                state = (b + 1, a, d, c)
                nxt[state] = (nxt.get(state, 0) + ways) % mod
            if allow_b:
                state = (c + 1, d, a, b)
                nxt[state] = (nxt.get(state, 0) + ways) % mod
            if allow_c:
                state = (d + 1, c, b, a)
                nxt[state] = (nxt.get(state, 0) + ways) % mod
        dp = nxt

    answer = 0
    for counts, ways in dp.items():
        good = sum(v * (v - 1) // 2 for v in counts)
        if good >= k:
            answer += ways
    return answer % mod

