def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """Count proper three-colour completions modulo 998244353.

    Each '?' can be replaced with '1', '2', or '3'; all edge-sharing
    cells must have different digits. H and W are positive and H * W <= 200.
    """
    mod = 998244353

    # Keep the frontier along the shorter dimension (at most 14 cells).
    if W > H:
        grid = ["".join(grid[r][c] for r in range(H)) for c in range(W)]
        H, W = W, H

    # Two bits per frontier cell. Zero denotes a cell outside the grid.
    # The oldest cell is the upper neighbour; the newest is the left one.
    mask = (1 << (2 * W)) - 1
    upper_shift = 2 * (W - 1)
    dp = {0: 1}
    choices = {
        (up, left): tuple(c for c in (1, 2, 3) if c != up and c != left)
        for up in range(4)
        for left in range(4)
    }
    for row in grid:
        for col, cell in enumerate(row):
            next_dp = {}
            fixed = 0 if cell == "?" else int(cell)
            for state, ways in dp.items():
                up = state >> upper_shift
                left = (state & 3) if col else 0
                base = (state << 2) & mask
                if fixed:
                    if fixed == up or fixed == left:
                        continue
                    new_state = base | fixed
                    next_dp[new_state] = (next_dp.get(new_state, 0) + ways) % mod
                else:
                    for colour in choices[up, left]:
                        new_state = base | colour
                        next_dp[new_state] = (next_dp.get(new_state, 0) + ways) % mod
            dp = next_dp
            if not dp:
                return 0
    return sum(dp.values()) % mod

def can_transform(k: int, s: str, t: str) -> bool:
    """Determine whether insertions, deletions, and replacements can turn
    s into t using at most k operations.

    The strings may have up to 500000 characters and k is at most 20.
    """
    n, m = len(s), len(t)
    if abs(n - m) > k:
        return False
    if max(n, m) <= k:
        return True

    # A diagonal is i - j. Keep only the furthest source position on each
    # diagonal, extending every state through all immediately matching letters.
    i = 0
    while i < n and i < m and s[i] == t[i]:
        i += 1
    if i == n and i == m:
        return True
    frontier = {0: i}

    for _ in range(k):
        next_frontier = {}
        for diagonal, i in frontier.items():
            j = i - diagonal
            if i < n:
                # Delete s[i].
                new_diagonal = diagonal + 1
                if i + 1 > next_frontier.get(new_diagonal, -1):
                    next_frontier[new_diagonal] = i + 1
            if j < m:
                # Insert t[j].
                new_diagonal = diagonal - 1
                if i > next_frontier.get(new_diagonal, -1):
                    next_frontier[new_diagonal] = i
            if i < n and j < m:
                # Replace s[i] with t[j].
                if i + 1 > next_frontier.get(diagonal, -1):
                    next_frontier[diagonal] = i + 1

        for diagonal, i in next_frontier.items():
            j = i - diagonal
            while i < n and j < m and s[i] == t[j]:
                i += 1
                j += 1
            if i == n and j == m:
                return True
            next_frontier[diagonal] = i
        frontier = next_frontier

    return False

from functools import lru_cache
from math import gcd


@lru_cache(maxsize=None)
def _suffix_count(length: int, digit_sum: int, divisor: int) -> int:
    """Count nonzero-digit suffixes with the required sum and divisibility."""
    if digit_sum < length or digit_sum > 9 * length:
        return 0
    if length == 0:
        return int(digit_sum == 0 and divisor == 1)
    return sum(
        _suffix_count(length - 1, digit_sum - digit, divisor // gcd(divisor, digit))
        for digit in range(1, 10)
    )


def _possible_sums(limit: int):
    # A nonzero digit product has no prime factors other than 2, 3, 5, 7.
    for total in range(1, limit + 1):
        rest = total
        for prime in (2, 3, 5, 7):
            while rest % prime == 0:
                rest //= prime
        if rest == 1:
            yield total


@lru_cache(maxsize=None)
def _short_beautiful(length: int) -> int:
    return sum(_suffix_count(length, total, total)
               for total in _possible_sums(9 * length))


def _count_up_to(bound: int) -> int:
    if bound <= 0:
        return 0
    digits = tuple(map(int, str(bound)))
    size = len(digits)

    # Count all positive numbers with nonzero digits up to the bound.
    nonzero = sum(9 ** length for length in range(1, size))
    for index, digit in enumerate(digits):
        remaining = size - index - 1
        nonzero += max(0, digit - 1) * 9 ** remaining
        if digit == 0:
            break
    else:
        nonzero += 1

    # Every number with an actual zero digit is beautiful.
    answer = bound - nonzero
    answer += sum(_short_beautiful(length) for length in range(1, size))

    # Count beautiful numbers of the bound's length by their digit sum.
    for total in _possible_sums(9 * size):
        prefix_sum = 0
        divisor = total
        for index, digit in enumerate(digits):
            remaining = size - index - 1
            for smaller in range(1, digit):
                answer += _suffix_count(
                    remaining, total - prefix_sum - smaller,
                    divisor // gcd(divisor, smaller),
                )
            if digit == 0:
                break
            prefix_sum += digit
            divisor //= gcd(divisor, digit)
        else:
            answer += int(prefix_sum == total and divisor == 1)
    return answer


def count_beautiful_numbers(l: int, r: int) -> int:
    """Count beautiful positive integers in the inclusive range [l, r].

    A number is beautiful when its digit product is divisible by its digit sum.
    Constraints: 1 <= l <= r < 10**9.

    >>> count_beautiful_numbers(10, 20)
    2
    >>> count_beautiful_numbers(1, 15)
    10
    >>> count_beautiful_numbers(4, 4)
    1
    """
    return _count_up_to(r) - _count_up_to(l - 1)

